function (vars) {
	var g = new GridWidget(vars.element, vars.dataSource);
	g.groupable = false;
	g.searchable = false;
	g.pageable = false;
	g.scrollable = false;
	g.editable = false;
	g.exports = true;
	
	g.columns = [
		{
			field: "User.Id",
			title: "[resource_shortdisplayname[UserId]]",
			description: "[resource_description[UserId]]",
			type: "string",
			width: 80
		},
        {
			field: "User.UserEmail",
			format: "{0:" + type.dateFormat + "}",
			title: "[resource_shortdisplayname[UserEmail]]",
			description: "[resource_description[UserEmail]]",
			type: "string"
		},
		{
			field: "Sessions",
			title: "[resource_shortdisplayname[Sessions]]",
			description: "[resource_description[Sessions]]",
			width: 70
		},
        {
			field: "PageRequests",
			title: "[resource_shortdisplayname[PageHits]]",
			description: "[resource_description[PageHits]]",
			width: 70
		},
        {
			field: "ApiRequests",
			title: "[resource_shortdisplayname[ApiHits]]",
			description: "[resource_description[ApiHits]]",
			width: 100
		}
	];
	return g;
}
